// supabase/functions/_shared/http.ts
var APP_ORIGIN = new URL(APP_URL).origin;
var allowedOrigins = new Set([
  APP_ORIGIN,
  ...(Deno.env.get("EXTRA_ALLOWED_ORIGINS") ?? "").split(",")
].map((o) => o.trim().replace(/\/$/, "")).filter(Boolean));
function corsHeaders(req) {
  const origin = req.headers.get("origin") ?? "";
  return {
    "Access-Control-Allow-Origin": allowedOrigins.has(origin) ? origin : APP_ORIGIN,
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    Vary: "Origin"
  };
}
function json(req, body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders(req),
      "Content-Type": "application/json"
    }
  });
}
var HttpError = class extends Error {
  status;
  details;
  constructor(status, message, details) {
    super(message), this.status = status, this.details = details;
  }
};
function serve(handler) {
  Deno.serve(async (req) => {
    if (req.method === "OPTIONS") return new Response("ok", {
      headers: corsHeaders(req)
    });
    if (req.method !== "POST") return json(req, {
      error: "Method not allowed"
    }, 405);
    try {
      let body;
      try {
        body = await req.json();
      } catch {
        throw new HttpError(400, "Invalid JSON body");
      }
      if (!body || typeof body !== "object" || Array.isArray(body)) throw new HttpError(400, "Invalid JSON body");
      return json(req, await handler(req, body));
    } catch (err) {
      if (err instanceof HttpError) return json(req, {
        error: err.message,
        details: err.details
      }, err.status);
      console.error(err);
      return json(req, {
        error: "Something went wrong. Please try again."
      }, 500);
    }
  });
}
function clientIp(req) {
  return req.headers.get("cf-connecting-ip") ?? req.headers.get("x-forwarded-for")?.split(",")[0].trim() ?? "unknown";
}

// supabase/functions/_shared/db.ts
var db = createClient(Deno.env.get("SUPABASE_URL"), Deno.env.get("SUPABASE_SERVICE_ROLE_KEY"), {
  auth: {
    persistSession: false,
    autoRefreshToken: false
  }
});
async function requireStaff(req, roles = [
  "admin",
  "scanner"
]) {
  const jwt = req.headers.get("authorization")?.replace(/^Bearer\s+/i, "");
  if (!jwt) throw new HttpError(401, "Not signed in");
  const { data, error } = await db.auth.getUser(jwt);
  if (error || !data.user) throw new HttpError(401, "Not signed in");
  const { data: staff } = await db.from("admin_users").select("email, role, active").eq("user_id", data.user.id).maybeSingle();
  if (!staff?.active || !roles.includes(staff.role)) throw new HttpError(403, roles.length === 1 && roles[0] === "admin" ? "Admins only" : "Staff only");
  return {
    userId: data.user.id,
    email: staff.email,
    role: staff.role
  };
}
async function loadEvent(id) {
  const { data, error } = await db.from("events").select("*").eq("id", id).single();
  if (error) throw error;
  return data;
}

// supabase/functions/_shared/email.ts
var sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
var ResendProvider = class {
  apiKey;
  from;
  // Resend's default limit is 2 requests/second per team; space sends out so bulk approvals don't 429.
  nextSlot;
  minIntervalMs;
  constructor(apiKey, from) {
    this.apiKey = apiKey;
    this.from = from;
    this.nextSlot = 0;
    this.minIntervalMs = Number(Deno.env.get("EMAIL_MIN_INTERVAL_MS") ?? 550);
  }
  async send(message) {
    const payload = {
      from: this.from,
      to: [
        message.to
      ],
      subject: message.subject,
      html: message.html,
      text: message.text,
      reply_to: message.replyTo,
      attachments: message.attachments?.map((a) => ({
        filename: a.filename,
        content: a.content,
        content_type: a.contentType,
        content_id: a.contentId
      }))
    };
    for (let attempt = 0; attempt < 3; attempt++) {
      const wait = this.nextSlot - Date.now();
      if (wait > 0) await sleep(wait);
      this.nextSlot = Date.now() + this.minIntervalMs;
      const res = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${this.apiKey}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        const body = await res.json();
        return {
          status: "sent",
          messageId: body.id
        };
      }
      if (res.status === 429 || res.status >= 500) {
        await sleep(1e3 * (attempt + 1));
        continue;
      }
      return {
        status: "failed",
        error: `Resend ${res.status}: ${(await res.text()).slice(0, 500)}`
      };
    }
    return {
      status: "failed",
      error: "Resend: gave up after 3 attempts (rate limited or unavailable)"
    };
  }
};
var ConsoleProvider = class {
  send(message) {
    console.log(`[email:dev] to=${message.to} subject="${message.subject}"
${message.text}`);
    return Promise.resolve({
      status: "skipped",
      error: "RESEND_API_KEY not set \u2014 email logged, not sent"
    });
  }
};
var resendKey = Deno.env.get("RESEND_API_KEY");
var emailProvider = resendKey ? new ResendProvider(resendKey, Deno.env.get("EMAIL_FROM") ?? Deno.env.get("RESEND_FROM_EMAIL") ?? "Youth Innovations Marketplace <register@youthinnovationsmarketplace.org>") : new ConsoleProvider();

